SET default_transaction_read_only=on;
SELECT partner_slug,status,rcap_policy_version,operating_model,landing_page_ready,launched_at IS NOT NULL launched FROM partner_onboarding WHERE partner_slug='independent-qa-1791680881148';
SELECT approval_type,decision,reviewer_user_id IS NOT NULL has_actor,policy_details FROM partner_onboarding_launch_approvals a JOIN partner_onboarding w ON w.id=a.workspace_id WHERE w.partner_slug='independent-qa-1791680881148';
SELECT session_id,jurisdiction,(SELECT count(*) FROM jsonb_object_keys(s.answers)) answer_count,current_question_id,status,partner_slug,partner_benefit_active FROM screening_sessions s WHERE session_id='69f4d217-bb94-41e2-b13b-2e9984b57279';
SELECT p.status,p.jurisdiction,p.partner_slug,p.claimed_matter_id,p.claimed_user_id=m.user_id same_owner,p.anonymous_session_id::text=m.source_session_id same_session,m.payment_status,m.amount_cents,m.packet_status FROM consumer_pending_screening_results p JOIN consumer_briefcase_items m ON m.source_pending_result_id=p.pending_id WHERE m.id='cfe217ac-171a-4379-a16f-a1085bed5fb2';
SELECT s.id,s.status,s.ended_reason,s.ended_at IS NOT NULL ended,s.consent_version,s.consented_at IS NOT NULL consented,c.matter_id,c.participant_user_id=s.participant_user_id participant_owned FROM clinic_assisted_sessions s JOIN clinic_cases c ON c.assisted_session_id=s.id WHERE s.event_id='d0190a83-1556-478e-82bf-c64ae2197254';
SELECT reset_binding_supported,assisted_session_id IS NOT NULL has_assistance,closed_at IS NOT NULL preconsent_closed FROM clinic_event_access_redemptions WHERE event_id='d0190a83-1556-478e-82bf-c64ae2197254';
SELECT action,count(*) FROM clinic_event_audit WHERE event_id='d0190a83-1556-478e-82bf-c64ae2197254' GROUP BY action ORDER BY action;
SELECT id,payment_status,amount_cents,currency,packet_status,payment_authority FROM consumer_briefcase_items WHERE id='4d1672bf-9d80-44b9-9700-019aa777d4e2';
SELECT count(*) protected_artifacts FROM consumer_packet_artifact_provenance WHERE briefcase_item_id='4d1672bf-9d80-44b9-9700-019aa777d4e2';
SELECT p.proname,has_function_privilege('anon',p.oid,'execute') anon_execute,has_function_privilege('authenticated',p.oid,'execute') authenticated_execute,has_function_privilege('service_role',p.oid,'execute') service_execute FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('rcap_consumer_packet_authorized','rcap_service_clinic_program_options','clinic_start_assisted_session_for_entry','clinic_close_unassisted_entry','clinic_redeem_event_code_with_reset','rcap_service_save_clinic_follow_up','rcap_clinic_case_materials');
